// 1. Install dependencies: npm install lighthouse chrome-launcher

const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

async function runLighthouse() {
  // Launch headless Chrome
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
  const options = {
    port: chrome.port,
    output: 'json',
    onlyCategories: ['best-practices'],
    logLevel: 'info'
  };

  // Run Lighthouse against the target URL
  const runnerResult = await lighthouse('https://abcnews.go.com/', options);

  // Extract the relevant pieces
  const lhr = runnerResult.lhr;
  console.log('Best-practices -> Minify JavaScript Display Value:',
    lhr.audits['unminified-javascript'].displayValue);

  console.log('\n—— stackPacks array (should show duplicates):');
  lhr.stackPacks.forEach((pack, i) => {
    console.log(`${i}. id: ${pack.id}, title: ${pack.title}`);
  });

  // kill Chrome
  await chrome.kill();
}

runLighthouse().catch(err => console.error(err));
